import{_ as t,o,c as d,a3 as a}from"./chunks/framework.CcKC9xfe.js";const h=JSON.parse('{"title":"IMAP configuration","description":"IMAP configuration for yarilo: IMAP4rev2 (RFC 9051) with IMAP4rev1 compatibility, supported extensions, listener ports, TLS modes and protocol settings.","frontmatter":{"description":"IMAP configuration for yarilo: IMAP4rev2 (RFC 9051) with IMAP4rev1 compatibility, supported extensions, listener ports, TLS modes and protocol settings.","outline":[2,4],"head":[["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/protocols/imap.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/latest/protocols/imap.html"}],["meta",{"property":"og:title","content":"IMAP configuration"}],["meta",{"name":"twitter:title","content":"IMAP configuration"}],["meta",{"property":"og:description","content":"IMAP configuration for yarilo: IMAP4rev2 (RFC 9051) with IMAP4rev1 compatibility, supported extensions, listener ports, TLS modes and protocol settings."}],["meta",{"name":"twitter:description","content":"IMAP configuration for yarilo: IMAP4rev2 (RFC 9051) with IMAP4rev1 compatibility, supported extensions, listener ports, TLS modes and protocol settings."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/latest/protocols/imap.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/latest/protocols/imap.html\\",\\"headline\\":\\"IMAP configuration\\",\\"description\\":\\"IMAP configuration for yarilo: IMAP4rev2 (RFC 9051) with IMAP4rev1 compatibility, supported extensions, listener ports, TLS modes and protocol settings.\\",\\"dateModified\\":\\"2026-10-31T12:43:41.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/latest/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"IMAP configuration\\",\\"item\\":\\"https://doc.yarilomail.org/latest/protocols/imap.html\\"}]}]}"]]},"headers":[],"relativePath":"protocols/imap.md","filePath":"protocols/imap.md","lastUpdated":1793450621000}'),i={name:"protocols/imap.md"};function s(l,e,r,n,c,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="imap-configuration" tabindex="-1">IMAP configuration <a class="header-anchor" href="#imap-configuration" aria-label="Permalink to &quot;IMAP configuration&quot;">​</a></h1><p>Yarilo implements IMAP4rev2 (RFC 9051) with backward compatibility to IMAP4rev1 (RFC 3501).</p><p>Listeners: <code>services.<wbr>imaps</code> (implicit TLS, port 993) and <code>services.<wbr>imap</code> (STARTTLS, port 143). See <a href="/latest/architecture/services.html">Services configuration</a> for listener-level settings (port, ssl_mode, haproxy_protocol, etc.).</p><hr><h2 id="protocol-imap" tabindex="-1"><code>protocol.<wbr>imap</code> <a class="header-anchor" href="#protocol-imap" aria-label="Permalink to &quot;`protocol.imap`&quot;">​</a></h2><p>Protocol-level behaviour, shared across both IMAP listeners.</p><h3 id="protocol.imap.imap_idle_notify_interval" tabindex="-1"><code>imap_<wbr>idle_<wbr>notify_<wbr>interval</code> <a class="header-anchor" href="#protocol.imap.imap_idle_notify_interval" aria-label="Permalink to &quot;`imap_idle_notify_interval` {#protocol.imap.imap_idle_notify_interval}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>120</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>protocol.imap.imap_idle_notify_interval</code></dd></dl></div><p>Interval between unsolicited EXISTS/RECENT responses during IDLE (RFC 2177 keepalive). <code>0</code> disables them.</p><h3 id="protocol.imap.imap_max_line_length" tabindex="-1"><code>imap_<wbr>max_<wbr>line_<wbr>length</code> <a class="header-anchor" href="#protocol.imap.imap_max_line_length" aria-label="Permalink to &quot;`imap_max_line_length` {#protocol.imap.imap_max_line_length}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>65536</code></dd><dt>Type</dt><dd>integer, bytes</dd><dt>Helm</dt><dd><code>protocol.imap.imap_max_line_length</code></dd></dl></div><p>Maximum IMAP command line length. <code>0</code> is unlimited.</p><h3 id="protocol.imap.imap_id_send" tabindex="-1"><code>imap_<wbr>id_<wbr>send</code> <a class="header-anchor" href="#protocol.imap.imap_id_send" aria-label="Permalink to &quot;`imap_id_send` {#protocol.imap.imap_id_send}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>name *</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>protocol.imap.imap_id_send</code></dd></dl></div><p>Space-separated key-value pairs sent in the ID response (RFC 2971). <code>*</code> means the server&#39;s own value. An empty string turns the ID extension off after login.</p><h3 id="protocol.imap.imap_id_retain" tabindex="-1"><code>imap_<wbr>id_<wbr>retain</code> <a class="header-anchor" href="#protocol.imap.imap_id_retain" aria-label="Permalink to &quot;`imap_id_retain` {#protocol.imap.imap_id_retain}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>protocol.imap.imap_id_retain</code></dd><dt>Added</dt><dd>2.4.5</dd></dl></div><p>Keep what a client sends in <code>ID</code> before login and pass it to the auth service, where the <a href="/latest/auth/policy.html">policy server</a> sees it as <code>device_<wbr>id</code>. The login&#39;s own <code>x-</code> keys are left out; at most 30 pairs and 256 bytes are kept.</p><h3 id="protocol.imap.login_greeting" tabindex="-1"><code>login_<wbr>greeting</code> <a class="header-anchor" href="#protocol.imap.login_greeting" aria-label="Permalink to &quot;`login_greeting` {#protocol.imap.login_greeting}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>protocol.imap.login_greeting</code></dd></dl></div><p>Replaces <code>IMAP server ready</code> in the <strong>backend&#39;s</strong> greeting. Clients behind a login proxy see <code>yarilo-imap-login</code>&#39;s own greeting, <code>Yarilo Login ready</code>, which this key does not change. Empty keeps the default.</p><h3 id="protocol.imap.imap_logout_format" tabindex="-1"><code>imap_<wbr>logout_<wbr>format</code> <a class="header-anchor" href="#protocol.imap.imap_logout_format" aria-label="Permalink to &quot;`imap_logout_format` {#protocol.imap.imap_logout_format}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>protocol.imap.imap_logout_format</code></dd></dl></div><p>Format of the line logged at session end; the variables are listed below. Empty logs no stats line.</p><h3 id="protocol.imap.imap_quota" tabindex="-1"><code>imap_<wbr>quota</code> <a class="header-anchor" href="#protocol.imap.imap_quota" aria-label="Permalink to &quot;`imap_quota` {#protocol.imap.imap_quota}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>true</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>protocol.imap.imap_quota</code></dd></dl></div><p>Advertise and serve the QUOTA extension (RFC 9208). Independent of quota enforcement.</p><h3 id="protocol.imap.imap_special_use_defaults" tabindex="-1"><code>imap_<wbr>special_<wbr>use_<wbr>defaults</code> <a class="header-anchor" href="#protocol.imap.imap_special_use_defaults" aria-label="Permalink to &quot;`imap_special_use_defaults` {#protocol.imap.imap_special_use_defaults}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>Archive: \\Archive, Drafts: \\Drafts, Junk: \\Junk, Sent: \\Sent, Trash: \\Trash</code></dd><dt>Type</dt><dd>map</dd><dt>Helm</dt><dd><code>protocol.imap.imap_special_use_defaults</code></dd></dl></div><p>Folder name (case-sensitive) to its RFC 6154 attribute, e.g. <code>Sent: &quot;\\\\Sent&quot;</code>. A user&#39;s own <code>CREATE (USE …)</code> wins.</p><h3 id="protocol.imap.imap_client_workarounds" tabindex="-1"><code>imap_<wbr>client_<wbr>workarounds</code> <a class="header-anchor" href="#protocol.imap.imap_client_workarounds" aria-label="Permalink to &quot;`imap_client_workarounds` {#protocol.imap.imap_client_workarounds}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>[]</code></dd><dt>Type</dt><dd>list</dd><dt>Values</dt><dd><code>tb-extra-mailbox-sep</code> <code>tb-lsub-flags</code></dd><dt>Also accepted as</dt><dd><code>client_workarounds</code></dd><dt>Helm</dt><dd><code>protocol.imap.client_workarounds</code></dd></dl></div><p>Compatibility shims for clients that break the protocol.</p><h3 id="imap-logout-format-variables" tabindex="-1"><code>imap_<wbr>logout_<wbr>format</code> variables <a class="header-anchor" href="#imap-logout-format-variables" aria-label="Permalink to &quot;`imap_logout_format` variables&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>%{deleted}</code></td><td style="text-align:left;">Number of messages marked <code>\\Deleted</code> in the session.</td></tr><tr><td style="text-align:left;"><code>%{expunged}</code></td><td style="text-align:left;">Number of messages expunged (removed from disk).</td></tr><tr><td style="text-align:left;"><code>%{fetch_<wbr>hdr_<wbr>count}</code></td><td style="text-align:left;">Number of header fetch operations.</td></tr><tr><td style="text-align:left;"><code>%{fetch_<wbr>hdr_<wbr>bytes}</code></td><td style="text-align:left;">Bytes transferred for header fetches.</td></tr><tr><td style="text-align:left;"><code>%{fetch_<wbr>body_<wbr>count}</code></td><td style="text-align:left;">Number of body fetch operations.</td></tr><tr><td style="text-align:left;"><code>%{fetch_<wbr>body_<wbr>bytes}</code></td><td style="text-align:left;">Bytes transferred for body fetches.</td></tr></tbody></table><p>Example:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">protocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  imap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    imap_logout_format</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;in=%{fetch_hdr_bytes}+%{fetch_body_bytes} expunged=%{expunged}&quot;</span></span></code></pre></div><hr><h2 id="recent-messages" tabindex="-1">Recent messages <a class="header-anchor" href="#recent-messages" aria-label="Permalink to &quot;Recent messages&quot;">​</a></h2><p>A message is <code>\\Recent</code> to the first session that selects its folder after the message arrives (RFC 3501). That session sees it in <code>* n RECENT</code>, in <code>FLAGS</code> and in <code>SEARCH RECENT</code>, <code>NEW</code> and <code>OLD</code>. Every later session sees it as old.</p><ul><li><code>SELECT</code> takes the folder&#39;s recent messages. Mail that arrives while the folder is selected is recent to that session.</li><li><code>EXAMINE</code> and <code>STATUS (RECENT)</code> report the recent messages and leave them for the next <code>SELECT</code>.</li><li>A virtual mailbox has recent messages of its own and is taken the same way. A folder its configuration names with <code>+</code> gives up its recent messages to that <code>SELECT</code>; see <a href="/latest/features/virtual.html">Virtual Mailboxes</a>.</li><li>A client cannot set <code>\\Recent</code>: <code>STORE</code> and <code>APPEND</code> with it are answered <code>BAD</code>.</li></ul><p>IMAP4rev2 removed <code>\\Recent</code>. After <code>ENABLE IMAP4rev2</code> the session gets no <code>RECENT</code> response and no <code>\\Recent</code> flag. Its <code>SELECT</code> still takes the recent messages, so a later IMAP4rev1 session sees them as old.</p><p>Each folder&#39;s index records which messages are no longer recent. An index written before this record existed reports every message as recent once, to the first <code>SELECT</code>.</p><hr><h2 id="supported-imap-extensions" tabindex="-1">Supported IMAP extensions <a class="header-anchor" href="#supported-imap-extensions" aria-label="Permalink to &quot;Supported IMAP extensions&quot;">​</a></h2><p><a href="/latest/architecture/parity.html#imap-extensions">Feature coverage</a> is the exhaustive list of what the server advertises. This table explains the ones that need it.</p><p><code>IMAP4rev2</code> also brings <code>ENABLE</code>, <code>SASL-IR</code>, <code>LITERAL+</code>, <code>SEARCHRES</code> and <code>STATUS=SIZE</code>; <code>LIST-EXTENDED</code>, <code>LIST-STATUS</code>, <code>CREATE-SPECIAL-USE</code> and <code>SORT</code> (RFC 5256, without <code>SORT=DISPLAY</code>) are advertised too.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Extension</th><th style="text-align:left;">RFC</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">IDLE</td><td style="text-align:left;">RFC 2177</td><td style="text-align:left;">Server-push new-mail notifications.</td></tr><tr><td style="text-align:left;">MOVE</td><td style="text-align:left;">RFC 6851</td><td style="text-align:left;">Atomic move (no COPY + STORE + EXPUNGE round-trip).</td></tr><tr><td style="text-align:left;">CONDSTORE</td><td style="text-align:left;">RFC 7162</td><td style="text-align:left;"><code>MODSEQ</code> flag, conditional STORE.</td></tr><tr><td style="text-align:left;">QRESYNC</td><td style="text-align:left;">RFC 7162</td><td style="text-align:left;">Fast mailbox resync after reconnect.</td></tr><tr><td style="text-align:left;">UIDPLUS</td><td style="text-align:left;">RFC 4315</td><td style="text-align:left;"><code>APPENDUID</code> / <code>COPYUID</code> response codes.</td></tr><tr><td style="text-align:left;">UNSELECT</td><td style="text-align:left;">RFC 3691</td><td style="text-align:left;">Close mailbox without expunge.</td></tr><tr><td style="text-align:left;">NAMESPACE</td><td style="text-align:left;">RFC 2342</td><td style="text-align:left;">Shared / Other Users namespaces.</td></tr><tr><td style="text-align:left;">QUOTA</td><td style="text-align:left;">RFC 9208</td><td style="text-align:left;">Per-user storage quota. Advertised while <code>imap_<wbr>quota</code> is on (the default).</td></tr><tr><td style="text-align:left;">ACL</td><td style="text-align:left;">RFC 4314</td><td style="text-align:left;">Per-mailbox access control lists. Advertised only with <code>acl.<wbr>enabled</code>. A body <code>FETCH</code> sets <code>\\Seen</code> only for a reader holding <code>s</code>; with <code>r</code> alone the body is served and the flag left as it is. <code>SELECT</code> answers <code>[READ-ONLY]</code> when the reader holds none of <code>i</code>, <code>e</code>, <code>w</code>, <code>t</code>, <code>s</code>.</td></tr><tr><td style="text-align:left;">BINARY</td><td style="text-align:left;">RFC 3516</td><td style="text-align:left;">Binary content transfer.</td></tr><tr><td style="text-align:left;">THREAD</td><td style="text-align:left;">RFC 5256</td><td style="text-align:left;">Threading of the searched messages, both algorithms: <code>THREAD=REFERENCES</code> (ancestry from <code>References</code> / <code>In-Reply-To</code>, then joining by base subject) and <code>THREAD=ORDEREDSUBJECT</code> (base subject alone). Computed per command from message headers.</td></tr><tr><td style="text-align:left;">ESEARCH</td><td style="text-align:left;">RFC 4731</td><td style="text-align:left;">Extended SEARCH with MIN/MAX/COUNT.</td></tr><tr><td style="text-align:left;">NOTIFY</td><td style="text-align:left;">RFC 5465</td><td style="text-align:left;">Event-based notifications. <code>NOTIFY SET</code>/<code>NONE</code> parsed with all mailbox filters; the <strong>selected</strong> mailbox honours <code>SELECTED</code> / <code>SELECTED-DELAYED</code> (MessageNew / MessageExpunge / FlagChange), suppressing the unsolicited responses the client did not request (RFC 5465 §5). <strong>Non-selected</strong> mailbox filters (PERSONAL / INBOXES / SUBSCRIBED / SUBTREE / MAILBOXES) are watched via the <code>pkg/<wbr>locks</code> event bus and their MessageNew / MessageExpunge / FlagChange activity is reported as untagged <code>* STATUS</code> (RFC 5465 §6), delivered during IDLE and before the next command&#39;s tagged response. The watched set is re-evaluated dynamically: mailboxes created, renamed or subscribed after <code>NOTIFY SET</code> join or leave the set live (via the per-user <code>mlist:</code> event key). Mailbox-level events - <strong>MailboxName</strong> (create / delete / rename, the last with <code>OLDNAME</code>) and <strong>SubscriptionChange</strong> (subscribe / unsubscribe) - are reported as untagged <code>* LIST</code> responses (RFC 5465 §5) when requested. <code>AnnotationChange</code> / metadata events are not yet reported.</td></tr><tr><td style="text-align:left;">SPECIAL-USE</td><td style="text-align:left;">RFC 6154</td><td style="text-align:left;"><code>\\Sent</code>, <code>\\Drafts</code>, <code>\\Trash</code> folder flags.</td></tr><tr><td style="text-align:left;">ID</td><td style="text-align:left;">RFC 2971</td><td style="text-align:left;">Server identity advertisement. Always offered before login; after login only while <code>imap_<wbr>id_<wbr>send</code> is non-empty.</td></tr><tr><td style="text-align:left;">OBJECTID</td><td style="text-align:left;">RFC 8474</td><td style="text-align:left;">Stable object identifiers: <code>MAILBOXID</code> (SELECT/EXAMINE response code + STATUS item, from the folder GUID), <code>EMAILID</code> (FETCH, from the message GUID), <code>THREADID</code> (FETCH, the conversation a message belongs to; <code>NIL</code> for accounts whose threading data has not been built yet). IDs are 32 lowercase hex chars of the 128-bit GUID; they survive RENAME.</td></tr><tr><td style="text-align:left;">METADATA</td><td style="text-align:left;">RFC 5464</td><td style="text-align:left;">Advertised only when a <code>metadata</code> dict is configured. Server and per-mailbox annotations (GETMETADATA / SETMETADATA). State lives in <code>cfg.<wbr>Dicts[&quot;metadata&quot;]</code> (<code>pkg/<wbr>dict</code>). Keys: <code>priv/<wbr>box/<wbr>&lt;folder_<wbr>guid&gt;/<wbr>&lt;entry&gt;</code> and <code>shared/<wbr>box/<wbr>&lt;folder_<wbr>guid&gt;/<wbr>&lt;entry&gt;</code>; server-scope entries live under INBOX&#39;s GUID with a <code>vendor/<wbr>yarilo/<wbr>pvt/<wbr>server/</code> prefix so they cannot collide with INBOX mailbox attributes.</td></tr></tbody></table>',48)])])}const g=t(i,[["render",s]]);export{h as __pageData,g as default};
